import json, re

with open('/private/tmp/claude-501/-Users-rina--claude/bcb2f2c2-3bd5-40de-a21c-025da566713f/scratchpad/batches/batch_0043.json', encoding='utf-8') as f:
    data = json.load(f)

jp_re = re.compile(r'[぀-ヿ一-鿿！-ﾟ]')

def jp_score(s):
    return len(jp_re.findall(s or ''))

def try_fixes(s):
    if not s:
        return s, 'none'
    candidates = [(s, 'orig')]
    try:
        candidates.append((s.encode('latin1').decode('utf-8'), 'latin1->utf8'))
    except Exception:
        pass
    try:
        candidates.append((s.encode('latin1').decode('cp932'), 'latin1->cp932'))
    except Exception:
        pass
    # pick candidate with max jp score, prefer non-orig if tie-breaking improvement
    best = max(candidates, key=lambda x: jp_score(x[0]))
    return best

changes = []
for d in data:
    for k in ['title','desc','body']:
        v = d.get(k) or ''
        fixed, method = try_fixes(v)
        if fixed != v:
            orig_score = jp_score(v)
            new_score = jp_score(fixed)
            if new_score > orig_score:
                d[k] = fixed
                changes.append((d['idx'], k, method, orig_score, new_score))

for c in changes:
    print(c)
print('total changes:', len(changes))

